sql:
SELECT 
  ABS(
    (SELECT lattice_constant FROM materials WHERE formula = 'Co3Ti') -
    (SELECT lattice_constant FROM materials WHERE formula = 'Ni3Al')
  ) AS lattice_constant_difference
LIMIT 10000;

SELECT formula
FROM material_entry
LIMIT 10000;

SELECT DISTINCT formula
FROM material_entry
LIMIT 10000;
